export const styles=`
:root{color-scheme:light;--bg:#f5f7fa;--surface:#fff;--surface-soft:#f8fafc;--ink:#111827;--muted:#5f6b7a;--subtle:#8793a1;--line:#d8e0e8;--line-strong:#b8c5d1;--navy:#16324f;--navy-2:#214766;--blue:#2563eb;--blue-soft:#eaf1ff;--green:#14805e;--green-soft:#e8f6f0;--amber:#9a6700;--amber-soft:#fff5d6;--red:#b42318;--red-soft:#fff0ed;--radius:7px;--shadow:0 8px 24px rgba(20,42,64,.08);font-family:"Source Sans 3",Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;font-synthesis:none}
*{box-sizing:border-box}html{scroll-behavior:smooth}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--ink);font-size:16px}body{min-width:0}button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{cursor:not-allowed}a{color:inherit}.hidden{display:none!important}.skip-link{position:fixed;left:16px;top:-80px;z-index:100;background:var(--navy);color:#fff;padding:10px 14px;border-radius:5px}.skip-link:focus{top:12px}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,[tabindex]:focus-visible{outline:3px solid rgba(37,99,235,.3);outline-offset:2px}
.app-shell{min-height:100dvh;display:grid;grid-template-columns:272px minmax(0,1fr)}.sidebar{min-width:0;background:var(--navy);color:#eaf0f5;padding:18px 14px;display:flex;flex-direction:column;gap:16px}.brand{padding:2px 8px 10px;border-bottom:1px solid rgba(255,255,255,.14)}.brand strong{display:block;font-size:17px;font-weight:700}.brand span{display:block;color:#a9bdcc;font-size:12px;margin-top:4px}.primary-nav{display:grid;gap:4px}.nav-button{min-height:44px;border:0;border-radius:6px;background:transparent;color:#b8cad7;text-align:left;padding:9px 11px;display:flex;align-items:center;justify-content:space-between;transition:background .18s ease,color .18s ease}.nav-button:hover{background:rgba(255,255,255,.08);color:#fff}.nav-button.active{background:#fff;color:var(--navy);font-weight:650}.nav-button small{font-size:11px;opacity:.72}.story-nav{min-height:0;display:flex;flex-direction:column;gap:8px;flex:1}.story-filters{display:grid;grid-template-columns:1fr 92px;gap:6px}.story-filters input,.story-filters select{width:100%;min-height:40px;border:1px solid rgba(255,255,255,.2);border-radius:5px;background:rgba(255,255,255,.08);color:#fff;padding:8px;font-size:12px}.story-filters select option{color:var(--ink)}.story-list{min-height:0;overflow:auto;border-top:1px solid rgba(255,255,255,.12);padding-top:8px}.story-group{margin:12px 8px 6px;color:#8fa7b8;font-size:11px;font-weight:700;text-transform:uppercase}.story-row{width:100%;border:0;border-left:3px solid transparent;background:transparent;color:#c5d3dd;text-align:left;padding:9px 8px;display:block;transition:background .18s ease,border-color .18s ease}.story-row:hover{background:rgba(255,255,255,.07)}.story-row.active{background:rgba(255,255,255,.1);border-left-color:#6ee7b7;color:#fff}.story-row strong{display:block;font-size:13px;line-height:1.25}.story-row span{display:flex;gap:6px;margin-top:5px;font-size:10px}.sidebar-foot{padding:10px 8px 0;border-top:1px solid rgba(255,255,255,.14);color:#9fb3c2;font:11px ui-monospace,SFMono-Regular,Menlo,monospace}
.workspace{min-width:0}.topbar{min-height:76px;background:rgba(255,255,255,.96);border-bottom:1px solid var(--line);padding:12px 22px;display:flex;align-items:center;justify-content:space-between;gap:18px;position:sticky;top:0;z-index:20;backdrop-filter:blur(10px)}.title h1{margin:0;font-size:19px;letter-spacing:0}.title p{margin:4px 0 0;color:var(--muted);font-size:12px}.runtime-controls{display:flex;align-items:center;gap:8px}.runtime-badge{min-height:40px;display:flex;align-items:center;gap:8px;padding:7px 10px;border:1px solid var(--line);border-radius:6px;background:var(--surface-soft);font-size:12px;white-space:nowrap}.dot{width:9px;height:9px;border-radius:50%;background:#98a3ad;flex:none}.dot.ready{background:var(--green);box-shadow:0 0 0 4px var(--green-soft)}.dot.starting,.dot.stopping{background:#d09a00}.dot.error{background:var(--red)}.segments{display:flex;border:1px solid var(--line);border-radius:6px;background:var(--surface-soft);padding:3px}.segment{min-height:36px;border:0;border-radius:4px;background:transparent;color:var(--muted);padding:7px 12px;font-size:12px}.segment.active{background:#fff;color:var(--navy);box-shadow:0 1px 3px rgba(20,42,64,.12);font-weight:650}.command{min-height:40px;border:1px solid var(--line-strong);border-radius:6px;background:#fff;color:var(--ink);padding:8px 13px;font-size:13px;transition:background .18s ease,border-color .18s ease}.command:hover:not(:disabled){background:var(--surface-soft);border-color:#8fa4b5}.command.primary{background:var(--green);border-color:var(--green);color:#fff;font-weight:650}.command.primary:hover:not(:disabled){background:#0d6d4f}.command.danger{border-color:#e6aba4;color:var(--red)}.command.danger:hover:not(:disabled){background:var(--red-soft)}.command:disabled{opacity:.45}.busy .command,.busy .segment,.busy .nav-button,.busy .story-row{pointer-events:none}
.toast{position:fixed;right:18px;top:90px;z-index:60;max-width:440px;padding:12px 14px;border-radius:6px;background:var(--navy);color:#fff;box-shadow:var(--shadow);font-size:13px;opacity:0;transform:translateY(-8px);pointer-events:none;transition:opacity .2s ease,transform .2s ease}.toast.visible{opacity:1;transform:translateY(0)}.toast.error{background:var(--red)}
.main{padding:20px 22px 42px;max-width:1720px;margin:0 auto}.view{display:none}.view.active{display:block}.view-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:16px}.view-head h2{font-size:20px;margin:0}.view-head p{font-size:13px;color:var(--muted);margin:5px 0 0;max-width:760px}.eyebrow{font-size:11px;font-weight:700;color:var(--blue);text-transform:uppercase}.badge{display:inline-flex;align-items:center;min-height:24px;padding:3px 7px;border-radius:4px;font-size:11px;font-weight:700;border:1px solid var(--line);background:var(--surface-soft);color:var(--muted)}.badge.success{color:var(--green);border-color:#9dd5c1;background:var(--green-soft)}.badge.warning{color:var(--amber);border-color:#e5c46e;background:var(--amber-soft)}.badge.error{color:var(--red);border-color:#e8aba4;background:var(--red-soft)}.badge.info{color:var(--blue);border-color:#a8c1f5;background:var(--blue-soft)}
.metrics-strip{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));border:1px solid var(--line);border-radius:var(--radius);background:var(--surface);overflow:hidden;margin-bottom:18px}.metric{padding:13px 14px;border-right:1px solid var(--line)}.metric:last-child{border-right:0}.metric span{display:block;color:var(--muted);font-size:11px}.metric strong{display:block;margin-top:5px;font-size:18px}.metric code{font-size:12px;overflow-wrap:anywhere}
.story-layout{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(360px,.85fr);gap:18px;align-items:start}.panel{min-width:0;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius)}.panel-gap{margin-top:16px}.panel-head{min-height:52px;padding:12px 15px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:12px}.panel-head h3{margin:0;font-size:14px}.panel-body{padding:16px}.story-title{font-size:22px;margin:7px 0 8px}.story-card{font-size:15px;line-height:1.6;margin:0;color:#273344}.story-meta{display:flex;gap:6px;flex-wrap:wrap}.boundary{margin:16px 0 0;padding:12px 14px;border-left:3px solid var(--blue);background:var(--blue-soft);font-size:13px;line-height:1.55;color:#24395a}.outcome{margin-top:16px;padding-top:14px;border-top:1px solid var(--line)}.outcome strong{font-size:12px;color:var(--muted)}.outcome p{margin:5px 0 0;font-size:14px}.checklist{margin:14px 0 0;padding:0;list-style:none;display:grid;gap:8px}.checklist li{display:grid;grid-template-columns:18px 1fr;gap:8px;line-height:1.45;font-size:13px}.checklist li:before{content:"";width:14px;height:14px;border:1px solid var(--line-strong);border-radius:3px;margin-top:2px;background:#fff}.scenario-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.scenario-head h3{margin:0;font-size:16px}.scenario-head p{margin:5px 0 0;color:var(--muted);font-size:12px;line-height:1.45}.step-progress{display:block;width:100%;margin-top:14px;height:5px;border:0;border-radius:99px;overflow:hidden;background:#e9eef3}.step-progress::-webkit-progress-bar{background:#e9eef3}.step-progress::-webkit-progress-value{background:var(--green)}.step-progress::-moz-progress-bar{background:var(--green)}.steps{display:grid;gap:0;margin-top:12px;border-top:1px solid var(--line)}.step{display:grid;grid-template-columns:34px minmax(0,1fr) auto;gap:10px;padding:12px 0;border-bottom:1px solid var(--line);align-items:start}.step-index{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:#edf1f5;color:var(--muted);font-size:12px;font-weight:700}.step.current .step-index{background:var(--blue);color:#fff}.step.pass .step-index{background:var(--green);color:#fff}.step.fail .step-index{background:var(--red);color:#fff}.step button{border:0;background:transparent;text-align:left;padding:0;color:inherit}.step strong{display:block;font-size:13px}.step p{margin:4px 0 0;color:var(--muted);font-size:12px;line-height:1.4}.step-result{font-size:11px;padding-top:6px;color:var(--muted)}.scenario-actions{display:flex;gap:8px;justify-content:flex-end;padding-top:14px}.inspector{position:sticky;top:96px}.inspector-tabs{display:flex;gap:2px}.tab-button{min-height:36px;border:0;background:transparent;color:var(--muted);padding:6px 10px;font-size:12px;border-bottom:2px solid transparent}.tab-button.active{color:var(--blue);border-bottom-color:var(--blue);font-weight:650}.result-summary{font-size:13px}.summary-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.summary-item{padding:10px;background:var(--surface-soft);border:1px solid var(--line);border-radius:5px}.summary-item span{display:block;color:var(--muted);font-size:10px}.summary-item strong{display:block;margin-top:4px;font-size:13px;overflow-wrap:anywhere}.json-view{margin:0;max-height:540px;overflow:auto;background:#10263a;color:#d9e7f1;border-radius:5px;padding:13px;font:12px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace;white-space:pre-wrap;overflow-wrap:anywhere}.empty{padding:26px 14px;text-align:center;color:var(--muted);font-size:13px}
.tool-layout{display:grid;grid-template-columns:238px minmax(360px,1fr) minmax(320px,.85fr);gap:16px;align-items:start}.tool-list{max-height:calc(100dvh - 180px);overflow:auto}.tool-row{width:100%;border:0;border-bottom:1px solid var(--line);background:#fff;text-align:left;padding:11px 12px;transition:background .18s ease}.tool-row:hover{background:var(--surface-soft)}.tool-row.active{background:var(--blue-soft);box-shadow:inset 3px 0 var(--blue)}.tool-row strong{display:block;font-size:12px}.tool-row span{display:block;color:var(--muted);font:10px ui-monospace,SFMono-Regular,Menlo,monospace;margin-top:4px}.tool-form-mode{display:flex;border-bottom:1px solid var(--line)}.tool-form-mode .tab-button{flex:1}.schema-form{display:grid;gap:13px}.field{display:grid;gap:5px}.field label,.fieldset>legend{font-size:12px;font-weight:650}.field label small,.fieldset>legend small{color:var(--muted);font-weight:400}.field input[type=text],.field input[type=number],.field select,.field textarea,.raw-editor{width:100%;min-height:42px;border:1px solid var(--line-strong);border-radius:5px;background:#fff;color:var(--ink);padding:9px 10px;font-size:13px}.field textarea,.raw-editor{min-height:88px;resize:vertical;font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.raw-editor{min-height:420px}.field.checkbox{display:flex;align-items:center;gap:9px;min-height:44px}.field.checkbox input{width:18px;height:18px}.fieldset{min-width:0;border:1px solid var(--line);border-radius:5px;padding:12px}.fieldset legend{padding:0 5px}.field-help{font-size:10px;color:var(--muted);line-height:1.4}.form-error{font-size:12px;color:var(--red);min-height:18px}.form-actions{display:flex;justify-content:space-between;gap:8px;margin-top:14px}.tool-response{position:sticky;top:96px}
.resource-layout{display:grid;grid-template-columns:280px minmax(0,1fr);gap:16px}.task-list{max-height:720px;overflow:auto}.task-row{width:100%;border:0;border-bottom:1px solid var(--line);background:#fff;text-align:left;padding:12px}.task-row.active{background:var(--green-soft);box-shadow:inset 3px 0 var(--green)}.task-row strong{display:block;font:12px ui-monospace,SFMono-Regular,Menlo,monospace;overflow-wrap:anywhere}.task-row span{display:flex;justify-content:space-between;gap:8px;margin-top:7px;color:var(--muted);font-size:11px}.resource-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.resource-card{min-width:0;border:1px solid var(--line);border-radius:6px;background:#fff;overflow:hidden}.resource-preview{aspect-ratio:16/9;background:#e9eef3;display:grid;place-items:center;overflow:hidden}.resource-preview img,.resource-preview video{width:100%;height:100%;object-fit:contain;background:#0c1721}.resource-preview code{padding:12px;font-size:11px;overflow-wrap:anywhere;text-align:center}.json-preview{width:100%;height:100%;margin:0;padding:12px;overflow:auto;background:#10263a;color:#d9e7f1;font:10px/1.45 ui-monospace,SFMono-Regular,Menlo,monospace;white-space:pre-wrap;overflow-wrap:anywhere}.resource-info{padding:10px}.resource-info strong{display:block;font-size:12px}.resource-info span{display:block;color:var(--muted);font-size:10px;margin-top:4px;overflow-wrap:anywhere}.compare-bar{display:grid;grid-template-columns:1fr 1fr auto;gap:8px;align-items:end;margin-bottom:14px}.compare-bar label{display:grid;gap:5px;font-size:11px;color:var(--muted)}.compare-bar select{min-height:42px;border:1px solid var(--line-strong);border-radius:5px;padding:8px;background:#fff}
.diagnostic-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(320px,.8fr);gap:16px;align-items:start}.history-scroll{max-height:720px;overflow:auto}.history-table{width:100%;border-collapse:collapse;font-size:12px}.history-table th,.history-table td{text-align:left;border-bottom:1px solid var(--line);padding:9px 10px;vertical-align:top}.history-table th{position:sticky;top:0;background:var(--surface-soft);color:var(--muted);font-size:10px}.history-table code{font-size:10px;overflow-wrap:anywhere}.diagnostic-side{display:grid;gap:16px}.control-group{display:grid;gap:9px}.control-group label{font-size:12px;font-weight:650}.control-group select{min-height:42px;border:1px solid var(--line-strong);border-radius:5px;padding:8px;background:#fff}.danger-zone{border-color:#e5aaa3}.danger-zone .panel-head{background:var(--red-soft)}.danger-list{display:grid;gap:10px}.danger-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding-bottom:10px;border-bottom:1px solid var(--line)}.danger-row:last-child{border-bottom:0;padding-bottom:0}.danger-row strong{display:block;font-size:13px}.danger-row span{display:block;color:var(--muted);font-size:11px;margin-top:3px}
dialog{width:min(520px,calc(100vw - 32px));border:0;border-radius:8px;padding:0;box-shadow:0 24px 80px rgba(9,25,40,.35)}dialog::backdrop{background:rgba(9,25,40,.56)}.dialog-head{padding:16px 18px;border-bottom:1px solid var(--line)}.dialog-head h3{margin:0;font-size:17px}.dialog-body{padding:18px}.dialog-body p{margin:0 0 12px;color:var(--muted);font-size:13px;line-height:1.55}.dialog-body label{display:grid;gap:6px;font-size:12px;font-weight:650}.dialog-body input{min-height:44px;border:1px solid var(--line-strong);border-radius:5px;padding:9px 10px}.dialog-actions{display:flex;justify-content:flex-end;gap:8px;padding:12px 18px;border-top:1px solid var(--line);background:var(--surface-soft)}
@media(max-width:1280px){.tool-layout{grid-template-columns:220px minmax(360px,1fr)}.tool-response{grid-column:1/-1;position:static}.resource-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:980px){.app-shell{grid-template-columns:minmax(0,1fr)}.sidebar{padding:12px 14px;display:block}.brand{display:inline-block;border:0;padding:4px 0 8px}.brand span,.sidebar-foot{display:none}.primary-nav{display:flex;gap:5px;overflow:auto;padding-bottom:4px}.nav-button{min-width:max-content}.story-nav{display:none}.topbar{position:static;align-items:flex-start;flex-direction:column;padding:13px 16px}.runtime-controls{width:100%;flex-wrap:wrap}.main{padding:16px}.story-layout,.diagnostic-grid{grid-template-columns:1fr}.inspector,.tool-response{position:static}.metrics-strip{grid-template-columns:repeat(3,minmax(0,1fr))}.metric:nth-child(3){border-right:0}.metric:nth-child(n+4){border-top:1px solid var(--line)}.tool-layout{grid-template-columns:1fr}.tool-list{max-height:240px}.resource-layout{grid-template-columns:1fr}.task-list{max-height:220px}}
@media(max-width:620px){html,body{font-size:16px}.runtime-badge{width:100%;justify-content:center}.segments{width:100%}.segment{flex:1;min-height:44px}.runtime-controls .command{flex:1;min-width:86px;min-height:44px}.metrics-strip{grid-template-columns:1fr 1fr}.metric{border-right:1px solid var(--line);border-top:1px solid var(--line)}.metric:nth-child(odd){border-right:1px solid var(--line)}.metric:nth-child(even){border-right:0}.metric:first-child,.metric:nth-child(2){border-top:0}.metric:last-child{grid-column:1/-1;border-right:0}.story-layout{gap:12px}.panel-body{padding:13px}.story-title{font-size:19px}.step{grid-template-columns:30px minmax(0,1fr)}.step-result{grid-column:2}.scenario-actions{display:grid;grid-template-columns:1fr 1fr}.scenario-actions .command{min-height:44px}.summary-grid{grid-template-columns:1fr}.tool-layout{display:block}.tool-layout>.panel{margin-bottom:12px}.resource-grid{grid-template-columns:1fr}.compare-bar{grid-template-columns:1fr}.view-head{display:block}.view-head .badge{margin-top:8px}.history-table{display:block;overflow:auto}.danger-row{align-items:flex-start;flex-direction:column}.danger-row .command{width:100%;min-height:44px}.toast{left:12px;right:12px;top:12px}.nav-button{min-height:44px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;transition:none!important;animation:none!important}}
`;

export const appScript=`
const state={session:null,capabilities:null,catalog:null,fixtures:[],tools:[],history:[],tasks:[],resources:[],view:'stories',selectedStoryId:null,selectedScenarioId:null,scenarioStep:0,scenarioResults:{},context:{primary:null,secondary:null,incomparable:null,outputs:{},last:null},selectedTool:null,formMode:'structured',busy:false,activeTaskId:null,inspectorMode:'summary',fault:'none'};
const toolLabels={create_video_analysis:'创建视频分析',get_analysis_status:'读取任务状态',cancel_analysis:'取消分析',get_quality_report:'读取质量报告',get_stroke_events:'读取动作片段',get_groundstroke_timing:'读取动作时序',get_motion_metrics:'读取相对指标',render_evidence_overlay:'渲染证据资源',generate_target_pose:'生成目标骨架',compare_sessions:'比较两次任务',export_review_package:'导出复核包',delete_analysis_data:'删除分析数据',runtime_status:'读取运行状态',runtime_prepare:'准备/变更运行环境',runtime_start:'启动运行环境',runtime_repair:'修复运行环境',runtime_uninstall:'卸载运行组件'};
const byId=id=>document.getElementById(id);
const safe=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const clone=value=>JSON.parse(JSON.stringify(value));
async function api(url,options={}){const response=await fetch(url,{headers:{'Content-Type':'application/json'},...options});const payload=await response.json().catch(()=>({error:{message:'Invalid server response'}}));if(!response.ok){const error=new Error(payload.error?.message||'Request failed');error.payload=payload;throw error;}return payload;}
function toast(message,error=false){const el=byId('toast');el.textContent=message;el.className='toast visible'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>{el.className='toast'},3200)}
function setBusy(value){state.busy=value;document.body.classList.toggle('busy',value);renderRuntimeControls()}
function statusBadge(value){const normalized=String(value||'unknown');const cls=['ready','complete','pass','success','deleted'].includes(normalized)?'success':['partial','limited','reshoot_required','unsupported','checking_input','cancelled'].includes(normalized)?'warning':['failed','error','safety_stop'].includes(normalized)?'error':'info';return '<span class="badge '+cls+'">'+safe(normalized)+'</span>'}
function renderRuntimeControls(){if(!state.session)return;const s=state.session;byId('runtime-dot').className='dot '+s.lifecycle;byId('runtime-state').textContent=s.lifecycle+' / '+s.backend.state;byId('runtime-version').textContent=s.backend.version||'not installed';document.querySelectorAll('[data-mode]').forEach(button=>button.classList.toggle('active',button.dataset.mode===s.mode));byId('start').disabled=state.busy||s.lifecycle==='ready'||s.lifecycle==='starting';byId('stop').disabled=state.busy||s.lifecycle==='stopped'||s.lifecycle==='stopping';byId('restart').disabled=state.busy||s.lifecycle==='stopped'||s.lifecycle==='starting'}
function switchView(view){state.view=view;document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.dataset.view===view));document.querySelectorAll('.nav-button').forEach(el=>el.classList.toggle('active',el.dataset.viewTarget===view));byId('story-nav').classList.toggle('hidden',view!=='stories');if(view==='tools')renderTools();if(view==='resources')renderResources();if(view==='diagnostics')renderDiagnostics()}
function coverageBadge(story){return story.coverage==='executable'?'<span class="badge success">可执行</span>':story.coverage==='partial'?'<span class="badge warning">部分验证</span>':'<span class="badge">WorkBuddy/人工</span>'}
function renderStoryList(){if(!state.catalog)return;const query=byId('story-search').value.trim().toLowerCase();const filter=byId('story-filter').value;let html='';let group='';for(const story of state.catalog.stories){if(filter!=='all'&&story.coverage!==filter)continue;if(query&&!([story.id,story.title,story.group].join(' ').toLowerCase().includes(query)))continue;if(group!==story.group){group=story.group;html+='<div class="story-group">'+safe(group)+'</div>'}html+='<button class="story-row '+(story.id===state.selectedStoryId?'active':'')+'" data-story="'+safe(story.id)+'"><strong>'+safe(story.id+' '+story.title)+'</strong><span>'+coverageBadge(story)+'<em>'+safe(story.priority)+'</em></span></button>'}byId('story-list').innerHTML=html||'<div class="empty">没有匹配的用户故事</div>';document.querySelectorAll('[data-story]').forEach(button=>button.addEventListener('click',()=>selectStory(button.dataset.story)))}
function selectStory(id){const story=state.catalog.stories.find(item=>item.id===id);if(!story)return;state.selectedStoryId=id;state.selectedScenarioId=story.scenario_id;state.scenarioStep=0;state.scenarioResults={};state.context={primary:null,secondary:null,incomparable:null,outputs:{},last:null};renderStoryList();renderStoryDetail();renderScenario();renderInspector();if(window.innerWidth<980)byId('main').scrollIntoView({behavior:'smooth'})}
function renderCoverageMetrics(){const stories=state.catalog.stories;const executable=stories.filter(x=>x.coverage==='executable').length;const partial=stories.filter(x=>x.coverage==='partial').length;const external=stories.filter(x=>x.coverage==='external').length;byId('story-count').textContent=stories.length;byId('executable-count').textContent=executable;byId('partial-count').textContent=partial;byId('external-count').textContent=external;byId('scenario-count').textContent=state.catalog.scenarios.length}
function renderStoryDetail(){const story=state.catalog.stories.find(item=>item.id===state.selectedStoryId);if(!story)return;byId('story-detail').innerHTML='<div class="story-meta"><span class="badge info">'+safe(story.id)+'</span><span class="badge">'+safe(story.priority)+'</span>'+coverageBadge(story)+'</div><h2 class="story-title">'+safe(story.title)+'</h2><p class="story-card">'+safe(story.card)+'</p><div class="boundary"><strong>验证边界</strong><br>'+safe(story.boundary)+'</div><div class="outcome"><strong>完成结果</strong><p>'+safe(story.outcome)+'</p></div><ul class="checklist">'+story.confirmations.map(item=>'<li>'+safe(item)+'</li>').join('')+'</ul>'}
function selectedScenario(){return state.catalog.scenarios.find(item=>item.id===state.selectedScenarioId)||null}
function renderScenario(){const scenario=selectedScenario();const wrap=byId('scenario-content');if(!scenario){wrap.innerHTML='<div class="empty">该故事由 WorkBuddy、专家编排或人工流程负责，本工作台不伪造可执行步骤。</div>';return}const completed=Object.values(state.scenarioResults).filter(x=>x==='pass').length;const current=Math.min(state.scenarioStep,scenario.steps.length-1);wrap.innerHTML='<div class="scenario-head"><div><h3>'+safe(scenario.title)+'</h3><p>'+safe(scenario.summary)+'</p></div><span class="badge '+(scenario.default_mode==='fixture'?'warning':'info')+'">'+safe(scenario.default_mode)+'</span></div><progress class="step-progress" max="'+scenario.steps.length+'" value="'+completed+'" aria-label="场景完成进度"></progress><div class="steps">'+scenario.steps.map((step,index)=>{const result=state.scenarioResults[step.id];const cls=(result||index===current)?' '+(result||'current'):'';return '<div class="step'+cls+'"><span class="step-index">'+(result==='pass'?'OK':index+1)+'</span><button data-step-index="'+index+'"><strong>'+safe(step.label)+'</strong><p>'+safe(step.detail)+'</p></button><span class="step-result">'+safe(result==='pass'?step.expected:result==='fail'?'未通过':'')+'</span></div>'}).join('')+'</div><div class="scenario-actions"><button class="command" id="scenario-reset">重置场景</button><button class="command primary" id="scenario-run" '+(state.busy?'disabled':'')+'>'+(state.scenarioResults[scenario.steps[current]?.id]==='pass'?'重新运行':'运行当前步骤')+'</button></div>';document.querySelectorAll('[data-step-index]').forEach(button=>button.addEventListener('click',()=>{state.scenarioStep=Number(button.dataset.stepIndex);renderScenario()}));byId('scenario-reset').addEventListener('click',()=>{state.scenarioStep=0;state.scenarioResults={};state.context={primary:null,secondary:null,incomparable:null,outputs:{},last:null};renderScenario();renderInspector()});byId('scenario-run').addEventListener('click',runCurrentStep)}
function renderInspector(){const value=state.context.last;document.querySelectorAll('[data-inspector]').forEach(button=>button.classList.toggle('active',button.dataset.inspector===state.inspectorMode));if(!value){byId('inspector-body').innerHTML='<div class="empty">运行一个步骤后显示结构化结果和原始 JSON。</div>';return}if(state.inspectorMode==='json'){byId('inspector-body').innerHTML='<pre class="json-view">'+safe(JSON.stringify(value,null,2))+'</pre>';return}const response=value.response||value;const result=response.result||response;let items=[];if(result&&typeof result==='object'){for(const key of ['task_id','version','state','stage','status','kind','comparable','complete','redacted','package_id','simulation'])if(result[key]!==undefined)items.push([key,result[key]]);if(response.error)items.push(['error',response.error.code]);if(Array.isArray(result.issues))items.push(['issues',result.issues.length]);if(Array.isArray(result.events))items.push(['events',result.events.length]);if(Array.isArray(result.metrics))items.push(['metrics',result.metrics.length]);if(Array.isArray(result.resources))items.push(['resources',result.resources.length]);if(Array.isArray(result.changes))items.push(['changes',result.changes.length])}byId('inspector-body').innerHTML=items.length?'<div class="summary-grid">'+items.map(item=>'<div class="summary-item"><span>'+safe(item[0])+'</span><strong>'+safe(item[1])+'</strong></div>').join('')+'</div><div class="outcome"><strong>最近响应</strong><p>'+(response.ok===false?'操作返回结构化错误。':'结果已通过当前接口返回。')+'</p></div>':'<pre class="json-view">'+safe(JSON.stringify(value,null,2))+'</pre>'}
function makeConsent(guardian=false,purposes=['analysis','retest','diagnostics']){return {consent_id:'consent-'+crypto.randomUUID(),task_version:1,purposes,text_version:'consent-text-1',confirmed:true,guardian_simulated:guardian,recipient_digest:null,materials_digest:null}}
function targetStroke(fixture){const found=state.fixtures.find(x=>x.fixture_id===fixture);return ['forehand','single_backhand','double_backhand','serve','forehand_volley','backhand_volley','footwork'].includes(found?.stroke_kind)?found.stroke_kind:'forehand'}
function createParams(fixture,overrides={}){const user={age_band:'adult',handedness:'right',target_stroke:targetStroke(fixture),goal:'验证用户故事对应的本地分析结果',exercise_background:'固定样本测试，不代表真实用户水平',safety:'clear',...(overrides.user||{})};return {operation_id:'op-create-'+crypto.randomUUID(),fixture_id:fixture,media_ref:'media/'+fixture+'.mp4',user,consent:overrides.consent||makeConsent(user.age_band==='youth'),primary_route:'technical_diagnosis',auxiliary_routes:[],subject_id:null,mirror_confirmed:true,...overrides,user}}
function taskParams(task){if(!task)throw new Error('当前场景还没有任务');return {task_id:task.task_id,version:task.version}}
async function executeTool(name,params,expectedError=null){const payload=await api('/api/tools/'+encodeURIComponent(name),{method:'POST',body:JSON.stringify(params)});state.context.last=payload;await refreshDerived();const response=payload.response;if(expectedError){if(response?.error?.code!==expectedError)throw new Error('预期 '+expectedError+'，实际 '+(response?.error?.code||'success'));return response}if(!response?.ok)throw new Error((response?.error?.code||'TOOL_FAILED')+'：'+(response?.error?.user_action||'review'));harvestContext(name,params,response.result);return response}
function harvestContext(name,params,result){if(result&&result.task_id&&result.version){const task={task_id:result.task_id,version:result.version,state:result.state};if(name==='create_video_analysis'){if(!state.context.primary)state.context.primary=task;else if(!state.context.secondary)state.context.secondary=task;else state.context.incomparable=task}else{for(const key of ['primary','secondary','incomparable'])if(state.context[key]?.task_id===result.task_id)state.context[key]={...state.context[key],...task}}}state.context.outputs[name]=result}
async function waitTask(key){let task=state.context[key];if(!task)throw new Error('缺少任务');for(let index=0;index<40;index+=1){const response=await executeTool('get_analysis_status',taskParams(task));task={...task,...response.result};state.context[key]=task;if(!['draft','waiting_for_capability','checking_input','analyzing','researching','rendering'].includes(task.state))return response;await new Promise(resolve=>setTimeout(resolve,180))}throw new Error('任务在测试时间窗内未进入终态')}
function evidenceIds(){const quality=state.context.outputs.get_quality_report;return (quality?.evidence||[]).map(item=>item.evidence_id)}
function resourceIds(){return state.resources.filter(item=>!state.context.primary||item.task_id===state.context.primary.task_id).map(item=>item.resource_id)}
async function sessionAction(action,mode){state.session=await api('/api/session/'+action,{method:'POST',body:JSON.stringify(mode?{mode}:{})});renderRuntimeControls();return {session:state.session}}
async function runStep(step,scenario){switch(step.action){
  case 'session_start':return sessionAction('start',scenario.default_mode);
  case 'session_stop':return sessionAction('stop');
  case 'runtime_status':return executeTool('runtime_status',{runtime_requirement:'required'});
  case 'create_primary':{const response=await executeTool('create_video_analysis',createParams(scenario.fixture_id||'iphone-flat'));state.context.primary={task_id:response.result.task_id,version:response.result.version,state:response.result.state};return response}
  case 'wait_primary':return waitTask('primary');
  case 'quality_primary':return executeTool('get_quality_report',taskParams(state.context.primary));
  case 'strokes_primary':return executeTool('get_stroke_events',taskParams(state.context.primary));
  case 'timing_primary':return executeTool('get_groundstroke_timing',taskParams(state.context.primary));
  case 'metrics_primary':return executeTool('get_motion_metrics',taskParams(state.context.primary));
  case 'render_frame':return executeTool('render_evidence_overlay',{operation_id:'op-frame-'+crypto.randomUUID(),...taskParams(state.context.primary),evidence_ids:evidenceIds(),mode:'frame'});
  case 'render_trajectory':return executeTool('render_evidence_overlay',{operation_id:'op-trajectory-'+crypto.randomUUID(),...taskParams(state.context.primary),evidence_ids:evidenceIds(),mode:'trajectory'});
  case 'render_slow':return executeTool('render_evidence_overlay',{operation_id:'op-slow-'+crypto.randomUUID(),...taskParams(state.context.primary),evidence_ids:evidenceIds(),mode:'slow_motion'});
  case 'target_pose':return executeTool('generate_target_pose',{operation_id:'op-target-'+crypto.randomUUID(),...taskParams(state.context.primary),features:['更早完成准备','保持支撑连续','向前挥拍后恢复']});
  case 'create_youth_rejected':return executeTool('create_video_analysis',createParams('iphone-flat',{user:{age_band:'youth'},consent:makeConsent(false)}),'GUARDIAN_CONFIRMATION_REQUIRED');
  case 'create_youth_confirmed':{const response=await executeTool('create_video_analysis',createParams('iphone-flat',{user:{age_band:'youth'},consent:makeConsent(true)}));state.context.primary={task_id:response.result.task_id,version:response.result.version,state:response.result.state};return response}
  case 'create_subject_confirmed':{const response=await executeTool('create_video_analysis',createParams('multiple-subjects',{subject_id:'person-1'}));state.context.primary={task_id:response.result.task_id,version:response.result.version,state:response.result.state};return response}
  case 'create_safety_stop':{const response=await executeTool('create_video_analysis',createParams('iphone-flat',{user:{safety:'pain'}}));state.context.primary={task_id:response.result.task_id,version:response.result.version,state:response.result.state};if(response.result.state!=='safety_stop')throw new Error('未进入 safety_stop');return response}
  case 'cancel_primary':{let response=await executeTool('cancel_analysis',{operation_id:'op-cancel-'+crypto.randomUUID(),...taskParams(state.context.primary)});if(response.result.state!=='cancelled'){const created=await executeTool('create_video_analysis',createParams(scenario.fixture_id||'iphone-flat'));state.context.primary={task_id:created.result.task_id,version:created.result.version,state:created.result.state};response=await executeTool('cancel_analysis',{operation_id:'op-cancel-'+crypto.randomUUID(),...taskParams(state.context.primary)})}if(response.result.state!=='cancelled')throw new Error('任务未进入 cancelled');return response}
  case 'status_primary':return executeTool('get_analysis_status',taskParams(state.context.primary));
  case 'create_secondary':{const response=await executeTool('create_video_analysis',createParams(scenario.fixture_id||'iphone-flat'));state.context.secondary={task_id:response.result.task_id,version:response.result.version,state:response.result.state};return response}
  case 'wait_secondary':return waitTask('secondary');
  case 'compare_tasks':return executeTool('compare_sessions',{...taskParams(state.context.primary),other_task_id:state.context.secondary.task_id,other_version:state.context.secondary.version});
  case 'create_incomparable':{const response=await executeTool('create_video_analysis',createParams('gopro-flat'));state.context.incomparable={task_id:response.result.task_id,version:response.result.version,state:response.result.state};await waitTask('incomparable');return response}
  case 'compare_incomparable':{const response=await executeTool('compare_sessions',{...taskParams(state.context.primary),other_task_id:state.context.incomparable.task_id,other_version:state.context.incomparable.version});if(response.result.comparable!==false)throw new Error('反例被错误标记为可比');return response}
  case 'export_review':{const ids=resourceIds();if(!ids.length)throw new Error('没有可选择的资源');return executeTool('export_review_package',{operation_id:'op-export-'+crypto.randomUUID(),...taskParams(state.context.primary),selected_resource_ids:ids,consent:makeConsent(false,['diagnostics'])})}
  case 'delete_primary':{const phrase=state.context.primary.task_id;await confirmDanger('删除任务数据',phrase,'删除本地任务和派生资源；外部副本不受本地删除控制。');return executeTool('delete_analysis_data',{operation_id:'op-delete-'+crypto.randomUUID(),...taskParams(state.context.primary),scope:'task',confirmed:true})}
  default:throw new Error('未知场景步骤 '+step.action)
}}
async function runCurrentStep(){const scenario=selectedScenario();if(!scenario)return;const step=scenario.steps[state.scenarioStep];if(!step)return;setBusy(true);try{const value=await runStep(step,scenario);state.context.last=value;state.scenarioResults[step.id]='pass';toast(step.label+'：通过');if(state.scenarioStep<scenario.steps.length-1)state.scenarioStep+=1}catch(error){state.scenarioResults[step.id]='fail';state.context.last=error.payload||{error:error.message};toast(error.message,true)}finally{setBusy(false);renderScenario();renderInspector();renderResources();renderDiagnostics()}}
function toolExample(name){const task=state.tasks.find(item=>item.task_id===state.activeTaskId)||state.tasks[0]||state.context.primary||{task_id:'task-required',version:1};const resources=state.resources.filter(item=>item.task_id===task.task_id);const scope=(state.session?.mode||'python')+'-debug-console-v1';const examples={
  create_video_analysis:createParams(selectedScenario()?.fixture_id||'iphone-flat'),get_analysis_status:taskParams(task),cancel_analysis:{operation_id:'op-cancel-'+crypto.randomUUID(),...taskParams(task)},get_quality_report:taskParams(task),get_stroke_events:taskParams(task),get_groundstroke_timing:taskParams(task),get_motion_metrics:taskParams(task),render_evidence_overlay:{operation_id:'op-render-'+crypto.randomUUID(),...taskParams(task),evidence_ids:evidenceIds().length?evidenceIds():['evidence-required'],mode:'frame'},generate_target_pose:{operation_id:'op-target-'+crypto.randomUUID(),...taskParams(task),features:['更早准备','保持支撑连续']},compare_sessions:{...taskParams(task),other_task_id:state.tasks.find(item=>item.task_id!==task.task_id)?.task_id||'other-task-required',other_version:1},export_review_package:{operation_id:'op-export-'+crypto.randomUUID(),...taskParams(task),selected_resource_ids:resources.length?resources.map(x=>x.resource_id):['resource-required'],consent:makeConsent(false,['diagnostics'])},delete_analysis_data:{operation_id:'op-delete-'+crypto.randomUUID(),...taskParams(task),scope:'task',confirmed:true},runtime_status:{runtime_requirement:'required'},runtime_prepare:{operation_id:'op-prepare-'+crypto.randomUUID(),consent_confirmed:true,target_version:'0.1.0',intent:'prepare',scope_digest:scope},runtime_start:{operation_id:'op-start-'+crypto.randomUUID(),runtime_requirement:'required'},runtime_repair:{operation_id:'op-repair-'+crypto.randomUUID(),consent_confirmed:true,scope_digest:scope},runtime_uninstall:{operation_id:'op-uninstall-'+crypto.randomUUID(),confirmed:true,keep_project_data:true}};return clone(examples[name]||{})}
function normalizeSchema(schema){if(schema?.allOf){return schema.allOf.reduce((acc,item)=>({...acc,...normalizeSchema(item),properties:{...(acc.properties||{}),...(normalizeSchema(item).properties||{})}}),{})}if(schema?.anyOf){return normalizeSchema(schema.anyOf.find(item=>item.type!=='null')||schema.anyOf[0])}return schema||{}}
function valueAt(value,path){return path.reduce((current,key)=>current?.[key],value)}
function renderFields(schema,value,path=[]){schema=normalizeSchema(schema);if(schema.type==='object'||schema.properties){const required=new Set(schema.required||[]);return '<fieldset class="fieldset"><legend>'+(path.length?safe(path[path.length-1]):'请求参数')+'</legend><div class="schema-form">'+Object.entries(schema.properties||{}).map(([key,child])=>renderField(child,valueAt(value,[...path,key]),[...path,key],required.has(key))).join('')+'</div></fieldset>'}return renderField(schema,value,path,false)}
function renderField(rawSchema,value,path,required){const schema=normalizeSchema(rawSchema);const key=path[path.length-1]||'value';const data='data-field="'+safe(path.join('.'))+'"';const marker=required?' *':'';const help=[schema.description,schema.enum?'选项：'+schema.enum.join(' / '):'',schema.minLength?'最少 '+schema.minLength+' 字符':''].filter(Boolean).join('；');if(schema.type==='object'||schema.properties)return renderFields(schema,value,path);if(schema.type==='boolean'||typeof schema.const==='boolean')return '<div class="field checkbox"><input type="checkbox" '+data+' data-type="boolean" '+((value??schema.const)?'checked':'')+' '+(schema.const!==undefined?'disabled':'')+'><label>'+safe(key+marker)+'</label></div>';if(schema.enum)return '<div class="field"><label>'+safe(key+marker)+'</label><select '+data+' data-type="string">'+schema.enum.map(item=>'<option '+(item===value?'selected':'')+'>'+safe(item)+'</option>').join('')+'</select>'+(help?'<span class="field-help">'+safe(help)+'</span>':'')+'</div>';if(schema.type==='array')return '<div class="field"><label>'+safe(key+marker)+' <small>JSON 数组</small></label><textarea '+data+' data-type="json">'+safe(JSON.stringify(value??[],null,2))+'</textarea>'+(help?'<span class="field-help">'+safe(help)+'</span>':'')+'</div>';if(schema.type==='integer'||schema.type==='number')return '<div class="field"><label>'+safe(key+marker)+'</label><input type="number" '+data+' data-type="number" value="'+safe(value??schema.minimum??0)+'" '+(schema.minimum!==undefined?'min="'+schema.minimum+'"':'')+'></div>';const nullable=rawSchema?.anyOf?.some(item=>item.type==='null');return '<div class="field"><label>'+safe(key+marker)+'</label><input type="text" '+data+' data-type="string" data-nullable="'+nullable+'" value="'+safe(value??schema.const??'')+'" '+(schema.const!==undefined?'readonly':'')+'>'+(help?'<span class="field-help">'+safe(help)+'</span>':'')+'</div>'}
function setPath(target,path,value){let current=target;const parts=path.split('.');parts.forEach((part,index)=>{if(index===parts.length-1)current[part]=value;else current=current[part]||(current[part]={})})}
function readStructured(){const result={};for(const input of byId('schema-form').querySelectorAll('[data-field]')){let value;if(input.dataset.type==='boolean')value=input.checked;else if(input.dataset.type==='number')value=Number(input.value);else if(input.dataset.type==='json')value=JSON.parse(input.value||'[]');else value=input.dataset.nullable==='true'&&input.value===''?null:input.value;setPath(result,input.dataset.field,value)}return result}
function renderTools(){if(!state.tools.length)return;const selected=state.tools.find(item=>item.name===state.selectedTool)||state.tools[0];state.selectedTool=selected.name;byId('tool-list').innerHTML=state.tools.map(tool=>'<button class="tool-row '+(tool.name===selected.name?'active':'')+'" data-tool="'+safe(tool.name)+'"><strong>'+safe(toolLabels[tool.name]||tool.name)+'</strong><span>'+safe(tool.description.split(';')[0])+'</span></button>').join('');document.querySelectorAll('[data-tool]').forEach(button=>button.addEventListener('click',()=>{state.selectedTool=button.dataset.tool;renderTools()}));byId('tool-title').textContent=toolLabels[selected.name]||selected.name;byId('tool-method').textContent=selected.description.split(';')[0];const example=toolExample(selected.name);byId('schema-form').innerHTML=renderFields(selected.inputSchema,example);byId('raw-input').value=JSON.stringify(example,null,2);byId('structured-wrap').hidden=state.formMode!=='structured';byId('raw-wrap').hidden=state.formMode!=='raw';document.querySelectorAll('[data-form-mode]').forEach(button=>button.classList.toggle('active',button.dataset.formMode===state.formMode));renderToolResponse()}
function renderToolResponse(){const last=state.context.last;if(!last){byId('tool-response-body').innerHTML='<div class="empty">运行工具后显示响应、耗时和校验结果。</div>';return}byId('tool-response-body').innerHTML='<pre class="json-view">'+safe(JSON.stringify(last,null,2))+'</pre>'}
async function runSelectedTool(){const tool=state.tools.find(item=>item.name===state.selectedTool);if(!tool)return;setBusy(true);byId('form-error').textContent='';try{const params=state.formMode==='raw'?JSON.parse(byId('raw-input').value):readStructured();if(['delete_analysis_data','runtime_uninstall'].includes(tool.name)){const phrase=tool.name==='runtime_uninstall'?'UNINSTALL RUNTIME':String(params.task_id||'RESET ALL DEMO');await confirmDanger(toolLabels[tool.name],phrase,'该操作会改变本地数据或运行组件。')}const response=await executeTool(tool.name,params);state.context.last={response};toast(toolLabels[tool.name]+'：完成');renderToolResponse();renderResources();renderDiagnostics()}catch(error){const pointers=error.payload?.error?.pointers||[];byId('form-error').textContent=error.message+(pointers.length?'：'+pointers.join(', '):'');state.context.last=error.payload||{error:error.message};renderToolResponse();toast(error.message,true)}finally{setBusy(false)}}
async function hydrateJsonResources(){for(const element of document.querySelectorAll('[data-json-resource]')){try{const value=await api('/api/resource?path='+encodeURIComponent(element.dataset.jsonResource));element.textContent=JSON.stringify(value,null,2)}catch(error){element.textContent='JSON 预览失败：'+error.message}}}
function renderResources(){const taskOptions=state.tasks.map(task=>'<option value="'+safe(task.task_id)+'">'+safe(task.task_id+' · '+task.state)+'</option>').join('');byId('task-list').innerHTML=state.tasks.length?state.tasks.map(task=>'<button class="task-row '+(task.task_id===state.activeTaskId?'active':'')+'" data-task="'+safe(task.task_id)+'"><strong>'+safe(task.task_id)+'</strong><span><em>'+safe(task.fixture_id||task.mode)+'</em>'+statusBadge(task.state)+'</span></button>').join(''):'<div class="empty">当前模式还没有任务</div>';document.querySelectorAll('[data-task]').forEach(button=>button.addEventListener('click',()=>{state.activeTaskId=button.dataset.task;renderResources()}));if(!state.activeTaskId&&state.tasks[0])state.activeTaskId=state.tasks[0].task_id;const visible=state.resources.filter(resource=>!state.activeTaskId||resource.task_id===state.activeTaskId);byId('resource-grid').innerHTML=visible.length?visible.map(resource=>{const url='/api/resource?path='+encodeURIComponent(resource.path);const preview=resource.mime.startsWith('image/')?'<img loading="lazy" alt="'+safe(resource.kind)+'" src="'+url+'">':resource.mime.startsWith('video/')?'<video controls preload="metadata" src="'+url+'"></video>':resource.mime==='application/json'?'<pre class="json-preview" data-json-resource="'+safe(resource.path)+'">正在读取 JSON</pre>':'<code>'+safe(resource.mime)+'</code>';return '<article class="resource-card"><div class="resource-preview">'+preview+'</div><div class="resource-info"><strong>'+safe(resource.kind)+'</strong><span>'+safe(resource.path)+'</span><span>'+safe(resource.resource_id)+'</span></div></article>'}).join(''):'<div class="empty">运行证据渲染、目标姿态或导出步骤后显示资源。</div>';void hydrateJsonResources();byId('compare-a').innerHTML='<option value="">选择任务</option>'+taskOptions;byId('compare-b').innerHTML='<option value="">选择任务</option>'+taskOptions}
async function compareSelected(){const a=state.tasks.find(item=>item.task_id===byId('compare-a').value);const b=state.tasks.find(item=>item.task_id===byId('compare-b').value);if(!a||!b){toast('请选择两个任务',true);return}setBusy(true);try{await executeTool('compare_sessions',{task_id:a.task_id,version:a.version,other_task_id:b.task_id,other_version:b.version});state.inspectorMode='summary';switchView('stories');renderInspector();toast('比较完成')}catch(error){toast(error.message,true)}finally{setBusy(false)}}
function renderDiagnostics(){byId('history-body').innerHTML=state.history.length?state.history.map(item=>'<tr><td>'+safe(new Date(item.timestamp).toLocaleTimeString())+'</td><td><code>'+safe(item.tool)+'</code></td><td>'+safe(item.duration_ms)+' ms</td><td>'+statusBadge(item.outcome)+'</td><td><code>'+safe(item.code||'OK')+'</code></td></tr>').join(''):'<tr><td colspan="5" class="empty">暂无工具调用记录</td></tr>';byId('fault-mode').value=state.fault}
async function applyFault(){setBusy(true);try{const result=await api('/api/session/fault',{method:'POST',body:JSON.stringify({fault:byId('fault-mode').value})});state.session=result.session;state.fault=result.fault;renderRuntimeControls();toast('故障模式已更新')}catch(error){toast(error.message,true)}finally{setBusy(false)}}
function downloadHistory(){const blob=new Blob([JSON.stringify(state.history,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='tennis-debug-history.json';link.click();URL.revokeObjectURL(url)}
function confirmDanger(title,phrase,detail){return new Promise((resolve,reject)=>{const dialog=byId('confirm-dialog');byId('dialog-title').textContent=title;byId('dialog-detail').textContent=detail;byId('dialog-phrase').textContent=phrase;const input=byId('dialog-input');const confirm=byId('dialog-confirm');input.value='';confirm.disabled=true;input.oninput=()=>{confirm.disabled=input.value!==phrase};const cleanup=()=>{confirm.onclick=null;byId('dialog-cancel').onclick=null;dialog.oncancel=null};confirm.onclick=()=>{cleanup();dialog.close();resolve(true)};byId('dialog-cancel').onclick=()=>{cleanup();dialog.close();reject(new Error('操作已取消'))};dialog.oncancel=()=>{cleanup();reject(new Error('操作已取消'))};dialog.showModal();input.focus()})}
async function dangerAction(kind){try{if(kind==='cancel'){const task=state.tasks.find(item=>item.task_id===state.activeTaskId);if(!task)throw new Error('没有当前任务');await confirmDanger('取消任务','CANCEL','取消会保留已完成检查点，不会删除任务。');await executeTool('cancel_analysis',{operation_id:'op-cancel-'+crypto.randomUUID(),task_id:task.task_id,version:task.version})}else if(kind==='delete'){const task=state.tasks.find(item=>item.task_id===state.activeTaskId);if(!task)throw new Error('没有当前任务');await confirmDanger('删除任务',task.task_id,'删除本地任务和全部派生资源。');await executeTool('delete_analysis_data',{operation_id:'op-delete-'+crypto.randomUUID(),task_id:task.task_id,version:task.version,scope:'task',confirmed:true})}else if(kind==='reset'){await confirmDanger('重置全部演示数据','RESET ALL DEMO','删除调试目录中的全部演示任务，不卸载 runtime。');await executeTool('delete_analysis_data',{operation_id:'op-reset-'+crypto.randomUUID(),task_id:null,version:null,scope:'all_demo',confirmed:true})}else if(kind==='uninstall'){await confirmDanger('卸载运行组件','UNINSTALL RUNTIME','卸载本地运行组件并保留项目数据。');await executeTool('runtime_uninstall',{operation_id:'op-uninstall-'+crypto.randomUUID(),confirmed:true,keep_project_data:true})}toast('操作完成');await refreshAll()}catch(error){toast(error.message,true)}}
function applyTaskSnapshot(snapshot){state.tasks=snapshot.tasks.filter(item=>item.mode===state.session.mode);state.resources=snapshot.resources.filter(item=>item.mode===state.session.mode);if(state.activeTaskId&&!state.tasks.some(item=>item.task_id===state.activeTaskId))state.activeTaskId=null;if(!state.activeTaskId&&state.tasks[0])state.activeTaskId=state.tasks[0].task_id}
async function refreshDerived(){const [history,tasks]=await Promise.all([api('/api/history'),api('/api/tasks')]);state.history=history.items;applyTaskSnapshot(tasks)}
async function refreshAll(){const [session,capabilities,catalog,fixtures,tools,history,tasks,fault]=await Promise.all([api('/api/session'),api('/api/capabilities'),api('/api/stories'),api('/api/fixtures'),api('/api/tools'),api('/api/history'),api('/api/tasks'),api('/api/session/fault')]);state.session=session;state.capabilities=capabilities;state.catalog=catalog;state.fixtures=fixtures.items;state.tools=tools.items;state.history=history.items;applyTaskSnapshot(tasks);state.fault=fault.fault;if(!state.selectedStoryId)state.selectedStoryId=catalog.stories.find(item=>item.scenario_id)?.id||catalog.stories[0]?.id;renderRuntimeControls();renderCoverageMetrics();renderStoryList();renderStoryDetail();state.selectedScenarioId=catalog.stories.find(item=>item.id===state.selectedStoryId)?.scenario_id||null;renderScenario();renderInspector();renderTools();renderResources();renderDiagnostics()}
async function lifecycle(name,mode){const changingMode=Boolean(mode&&state.session?.mode!==mode);setBusy(true);try{state.session=await api('/api/session/'+name,{method:'POST',body:JSON.stringify(mode?{mode}:{})});if(changingMode){state.scenarioStep=0;state.scenarioResults={};state.context={primary:null,secondary:null,incomparable:null,outputs:{},last:null};state.activeTaskId=null}renderRuntimeControls();toast(name==='stop'?'后端已停止':'后端已就绪');await refreshDerived()}catch(error){toast(error.message,true)}finally{setBusy(false)}}
document.querySelectorAll('[data-view-target]').forEach(button=>button.addEventListener('click',()=>switchView(button.dataset.viewTarget)));document.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>{if(state.session?.mode===button.dataset.mode)return;lifecycle(state.session?.lifecycle==='ready'?'restart':'start',button.dataset.mode)}));byId('start').addEventListener('click',()=>lifecycle('start',state.session?.mode||'python'));byId('stop').addEventListener('click',()=>lifecycle('stop'));byId('restart').addEventListener('click',()=>lifecycle('restart',state.session?.mode||'python'));byId('story-search').addEventListener('input',renderStoryList);byId('story-filter').addEventListener('change',renderStoryList);document.querySelectorAll('[data-inspector]').forEach(button=>button.addEventListener('click',()=>{state.inspectorMode=button.dataset.inspector;renderInspector()}));document.querySelectorAll('[data-form-mode]').forEach(button=>button.addEventListener('click',()=>{state.formMode=button.dataset.formMode;renderTools()}));byId('run-tool').addEventListener('click',runSelectedTool);byId('reset-tool').addEventListener('click',renderTools);byId('compare-run').addEventListener('click',compareSelected);byId('apply-fault').addEventListener('click',applyFault);byId('download-history').addEventListener('click',downloadHistory);document.querySelectorAll('[data-danger]').forEach(button=>button.addEventListener('click',()=>dangerAction(button.dataset.danger)));
refreshAll().catch(error=>toast(error.message,true));setInterval(()=>{if(!state.busy&&!document.hidden)api('/api/session').then(session=>{state.session=session;renderRuntimeControls()}).catch(()=>undefined)},2500);
`;

export const page=`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>网球用户故事测试工作台</title><link rel="stylesheet" href="/styles.css"></head><body><a class="skip-link" href="#main">跳到主要内容</a><div class="app-shell"><aside class="sidebar"><div class="brand"><strong>网球测试工作台</strong><span>非 WorkBuddy 后端验证</span></div><nav class="primary-nav" aria-label="工作区"><button class="nav-button active" data-view-target="stories">用户故事 <small>流程</small></button><button class="nav-button" data-view-target="tools">契约工具 <small>17</small></button><button class="nav-button" data-view-target="resources">任务资源 <small>本地</small></button><button class="nav-button" data-view-target="diagnostics">运行诊断 <small>安全</small></button></nav><section class="story-nav" id="story-nav" aria-label="用户故事列表"><div class="story-filters"><input id="story-search" type="search" aria-label="搜索用户故事" placeholder="搜索 US / 标题"><select id="story-filter" aria-label="筛选验证范围"><option value="all">全部</option><option value="executable">可执行</option><option value="partial">部分</option><option value="external">外部</option></select></div><div class="story-list" id="story-list"></div></section><div class="sidebar-foot">LOCAL ONLY<br>127.0.0.1 · Contract v1</div></aside><div class="workspace"><header class="topbar"><div class="title"><h1>用户故事测试工作台</h1><p>固定样本 · 冻结契约 · 可追溯结果</p></div><div class="runtime-controls"><div class="runtime-badge"><i class="dot" id="runtime-dot"></i><span id="runtime-state">loading</span><code id="runtime-version">—</code></div><div class="segments" aria-label="后端模式"><button class="segment" data-mode="python">Python</button><button class="segment" data-mode="fixture">Fixture</button></div><button class="command primary" id="start">启动</button><button class="command" id="restart">重启</button><button class="command" id="stop">停止</button></div></header><main class="main" id="main"><section class="view active" data-view="stories"><div class="view-head"><div><span class="eyebrow">V02 用户故事</span><h2>逐步验证非 WorkBuddy 能力</h2><p>所有故事均来自权威 Markdown。可执行场景调用真实 Contract API；模拟分析与未实现能力持续标识。</p></div><span class="badge info">来源：用户故事 V02</span></div><div class="metrics-strip"><div class="metric"><span>用户故事</span><strong id="story-count">—</strong></div><div class="metric"><span>可执行</span><strong id="executable-count">—</strong></div><div class="metric"><span>部分验证</span><strong id="partial-count">—</strong></div><div class="metric"><span>WorkBuddy / 人工</span><strong id="external-count">—</strong></div><div class="metric"><span>测试场景</span><strong id="scenario-count">—</strong></div></div><div class="story-layout"><div><article class="panel"><div class="panel-body" id="story-detail"><div class="empty">正在读取用户故事</div></div></article><section class="panel panel-gap"><div class="panel-head"><h3>场景步骤</h3><span class="badge">逐步执行</span></div><div class="panel-body" id="scenario-content"></div></section></div><aside class="panel inspector"><div class="panel-head"><h3>结果检查器</h3><div class="inspector-tabs"><button class="tab-button active" data-inspector="summary">摘要</button><button class="tab-button" data-inspector="json">JSON</button></div></div><div class="panel-body" id="inspector-body"></div></aside></div></section><section class="view" data-view="tools"><div class="view-head"><div><span class="eyebrow">Contract v1</span><h2>17 个工具通用调试器</h2><p>工具与 Schema 从 Contract Registry 动态加载；结构化表单和原始 JSON 共用同一服务端校验。</p></div><span class="badge success">无第二份工具清单</span></div><div class="tool-layout"><aside class="panel"><div class="panel-head"><h3>工具</h3><span class="badge">17</span></div><div class="tool-list" id="tool-list"></div></aside><section class="panel"><div class="panel-head"><div><h3 id="tool-title">—</h3><code id="tool-method">—</code></div></div><div class="tool-form-mode"><button class="tab-button active" data-form-mode="structured">结构化表单</button><button class="tab-button" data-form-mode="raw">原始 JSON</button></div><div class="panel-body"><div id="structured-wrap"><div id="schema-form" class="schema-form"></div></div><div id="raw-wrap" hidden><textarea class="raw-editor" id="raw-input" aria-label="原始 JSON 输入"></textarea></div><div class="form-error" id="form-error" role="alert"></div><div class="form-actions"><button class="command" id="reset-tool">恢复示例</button><button class="command primary" id="run-tool">运行工具</button></div></div></section><aside class="panel tool-response"><div class="panel-head"><h3>工具响应</h3><span class="badge">脱敏历史</span></div><div class="panel-body" id="tool-response-body"></div></aside></div></section><section class="view" data-view="resources"><div class="view-head"><div><span class="eyebrow">本地任务</span><h2>任务、资源与复测</h2><p>只预览当前调试数据根内、通过任务路径边界验证的资源。</p></div><span class="badge warning">目标姿态不是当前证据</span></div><div class="compare-bar"><label>基线任务<select id="compare-a"></select></label><label>复测任务<select id="compare-b"></select></label><button class="command primary" id="compare-run">比较</button></div><div class="resource-layout"><aside class="panel"><div class="panel-head"><h3>任务</h3><span class="badge">当前会话</span></div><div class="task-list" id="task-list"></div></aside><section class="panel"><div class="panel-head"><h3>安全资源预览</h3><span class="badge">PNG / MP4 / JSON</span></div><div class="panel-body"><div class="resource-grid" id="resource-grid"></div></div></section></div></section><section class="view" data-view="diagnostics"><div class="view-head"><div><span class="eyebrow">审计与恢复</span><h2>日志、故障和危险操作</h2><p>日志有界且脱敏；破坏性操作需要明确确认词。</p></div><button class="command" id="download-history">导出日志</button></div><div class="diagnostic-grid"><section class="panel"><div class="panel-head"><h3>工具调用历史</h3><span class="badge">最近 200 条</span></div><div class="history-scroll"><table class="history-table"><thead><tr><th>时间</th><th>工具</th><th>耗时</th><th>结果</th><th>代码</th></tr></thead><tbody id="history-body"></tbody></table></div></section><aside class="diagnostic-side"><section class="panel"><div class="panel-head"><h3>Fixture 故障注入</h3><span class="badge warning">SIMULATION</span></div><div class="panel-body control-group"><label for="fault-mode">故障模式</label><select id="fault-mode"><option value="none">none</option><option value="crash">crash</option><option value="invalid_response">invalid_response</option><option value="timeout">latency</option><option value="delete_partial">delete_partial</option></select><button class="command" id="apply-fault">应用并重启 Fixture</button></div></section><section class="panel danger-zone"><div class="panel-head"><h3>危险操作</h3><span class="badge error">需确认</span></div><div class="panel-body danger-list"><div class="danger-row"><div><strong>取消当前任务</strong><span>保留检查点和任务记录</span></div><button class="command" data-danger="cancel">取消</button></div><div class="danger-row"><div><strong>删除当前任务</strong><span>删除本地任务及派生资源</span></div><button class="command danger" data-danger="delete">删除</button></div><div class="danger-row"><div><strong>重置全部演示数据</strong><span>不卸载 runtime</span></div><button class="command danger" data-danger="reset">重置</button></div><div class="danger-row"><div><strong>卸载运行组件</strong><span>默认保留项目数据</span></div><button class="command danger" data-danger="uninstall">卸载</button></div></div></section></aside></div></section></main></div></div><div class="toast" id="toast" role="status" aria-live="polite"></div><dialog id="confirm-dialog"><div class="dialog-head"><h3 id="dialog-title">确认操作</h3></div><div class="dialog-body"><p id="dialog-detail"></p><label>输入 <code id="dialog-phrase"></code> 继续<input id="dialog-input" autocomplete="off"></label></div><div class="dialog-actions"><button class="command" id="dialog-cancel">取消</button><button class="command danger" id="dialog-confirm" disabled>确认执行</button></div></dialog><script src="/app.js"></script></body></html>`;
